CREATE OR REPLACE FUNCTION evm_enterprise_prod.gold.fn_rls_region_filter(region_param STRING)
RETURN
    IS_ACCOUNT_GROUP_MEMBER('GLOBAL_CFO')
    OR (IS_ACCOUNT_GROUP_MEMBER('VP_MENA') AND region_param = 'MENA')
    OR (IS_ACCOUNT_GROUP_MEMBER('VP_EMEA') AND region_param = 'EMEA')
    OR (IS_ACCOUNT_GROUP_MEMBER('VP_AMER') AND region_param = 'AMER')
    OR (IS_ACCOUNT_GROUP_MEMBER('VP_APAC') AND region_param = 'APAC');

ALTER TABLE evm_enterprise_prod.gold.fact_evm_daily
SET ROW FILTER evm_enterprise_prod.gold.fn_rls_region_filter ON (region_code);

CREATE OR REPLACE VIEW evm_enterprise_prod.gold.mv_evm_executive_metrics
WITH METRICS
LANGUAGE YAML
AS $$
version: 0.1
source: evm_enterprise_prod.gold.fact_evm_daily
dimensions:
  - name: snapshot_date
    expr: snapshot_date
  - name: region_code
    expr: region_code
  - name: project_sk
    expr: project_sk
measures:
  - name: budget_at_completion_usd
    expr: SUM(bac_usd)
  - name: planned_value_usd
    expr: SUM(cum_pv_usd)
  - name: earned_value_usd
    expr: SUM(cum_ev_usd)
  - name: actual_labor_cost_usd
    expr: SUM(cum_ac_labor_usd)
  - name: actual_cloud_cost_usd
    expr: SUM(cum_ac_cloud_usd)
  - name: actual_cost_total_usd
    expr: SUM(cum_ac_total_usd)
  - name: cost_variance_usd
    expr: SUM(cum_ev_usd) - SUM(cum_ac_total_usd)
  - name: schedule_variance_usd
    expr: SUM(cum_ev_usd) - SUM(cum_pv_usd)
  - name: cost_performance_index
    expr: ROUND(SUM(cum_ev_usd) / NULLIF(SUM(cum_ac_total_usd), 0), 4)
  - name: schedule_performance_index
    expr: ROUND(SUM(cum_ev_usd) / NULLIF(SUM(cum_pv_usd), 0), 4)
  - name: estimate_at_completion_usd
    expr: ROUND(SUM(bac_usd) / NULLIF(SUM(cum_ev_usd) / NULLIF(SUM(cum_ac_total_usd), 0), 0), 2)
  - name: eac_composite_usd
    expr: ROUND(SUM(cum_ac_total_usd) + ((SUM(bac_usd) - SUM(cum_ev_usd)) / NULLIF((SUM(cum_ev_usd) / NULLIF(SUM(cum_ac_total_usd), 0)) * (SUM(cum_ev_usd) / NULLIF(SUM(cum_pv_usd), 0)), 0)), 2)
  - name: variance_at_completion_usd
    expr: ROUND(SUM(bac_usd) - (SUM(bac_usd) / NULLIF(SUM(cum_ev_usd) / NULLIF(SUM(cum_ac_total_usd), 0), 0)), 2)
  - name: to_complete_performance_index
    expr: ROUND((SUM(bac_usd) - SUM(cum_ev_usd)) / NULLIF(SUM(bac_usd) - SUM(cum_ac_total_usd), 0), 4)
$$;
